@Mod.EventBusSubscriber(modid="thaumcraft")
public final class AuxiliaryProbe {
 public static final BlockPos P=new BlockPos(3520,205,8);static int ticks,stage;static long due;public static volatile boolean ready,framed;static boolean cancel;static ServerPlayer actor;
 static String mode(){return System.getProperty("thaumcraft.alchemyProbe","");}static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 static void place(ServerLevel l,BlockPos p,Block b){l.setBlockAndUpdate(p.below(),Blocks.DIRT.defaultBlockState());l.setBlockAndUpdate(p,b.defaultBlockState());}
 static ArcaneEarEntity ear(ServerLevel l,BlockPos p,boolean toggle){place(l,p,(toggle?AuxiliaryContent.TOGGLE:AuxiliaryContent.EAR).get());return (ArcaneEarEntity)l.getBlockEntity(p);}
 static void note(ServerLevel l,int n){var p=P.east(5);place(l,p,Blocks.NOTE_BLOCK);l.setBlockAndUpdate(p,l.getBlockState(p).setValue(NoteBlock.NOTE,n).setValue(NoteBlock.INSTRUMENT,NoteBlockInstrument.HARP));check(l.getBlockState(p).triggerEvent(l,p,0,0)!=cancel,"native note event cancellation");}
 static void paving(ServerLevel l){place(l,P.west(3),AuxiliaryContent.TRAVEL.get());var pig=(LivingEntity)net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getValue(net.minecraft.resources.Identifier.withDefaultNamespace("pig")).create(l,EntitySpawnReason.COMMAND);pig.setPos(Vec3.atBottomCenterOf(P.west(3).above()));l.getBlockState(P.west(3)).getBlock().stepOn(l,P.west(3),l.getBlockState(P.west(3)),pig);check(pig.getEffect(net.minecraft.world.effect.MobEffects.SPEED).getAmplifier()==1&&pig.getEffect(net.minecraft.world.effect.MobEffects.SPEED).getDuration()==40&&pig.getEffect(net.minecraft.world.effect.MobEffects.JUMP_BOOST).getAmplifier()==0,"original travel buffs");var field=P.west(6).above();check(l.getBlockState(field).is(AuxiliaryContent.FIELD.get())&&l.getBlockState(field.above()).is(AuxiliaryContent.FIELD.get()),"two-block native barrier field");check(!l.getBlockState(field).getCollisionShape(l,field,CollisionContext.of(pig)).isEmpty(),"barrier does not stop creature");var user=PrimordialProbe.fake(l);check(l.getBlockState(field).getCollisionShape(l,field,CollisionContext.of(user)).isEmpty(),"barrier stops player");l.setBlockAndUpdate(P.west(6).north(),Blocks.REDSTONE_BLOCK.defaultBlockState());check(l.getBlockState(field).getCollisionShape(l,field,CollisionContext.of(pig)).isEmpty(),"redstone did not disable barrier");l.removeBlock(P.west(6),false);check(!l.getBlockState(field).is(AuxiliaryContent.FIELD.get())&&!l.getBlockState(field.above()).is(AuxiliaryContent.FIELD.get()),"orphan barrier after removal");pig.discard();Thaumcraft.LOGGER.info("AUXILIARY_PAVING_OK: original speed/jump effects, two-high mob collision, player bypass, redstone override and orphan cleanup");}
 static void relay(ServerLevel l){var p=P.south(4);place(l,p,AuxiliaryContent.RELAY.get());var be=(RelayEntity)l.getBlockEntity(p);for(int i=0;i<7;i++)be.adjust(true);for(int i=0;i<9;i++)be.adjust(false);check(be.input()==8&&be.output()==9,"relay setting cycle");var q=p.north();l.setBlockAndUpdate(q.below(),Blocks.STONE.defaultBlockState());l.setBlock(q,Blocks.REDSTONE_WIRE.defaultBlockState(),2);l.setBlock(q,l.getBlockState(q).setValue(BlockStateProperties.POWER,7),2);((RelayBlock)l.getBlockState(p).getBlock()).reevaluate(l,p,l.getBlockState(p));check(!l.getBlockState(p).getValue(RelayBlock.ACTIVE),"below-threshold relay powered");l.setBlock(q,l.getBlockState(q).setValue(BlockStateProperties.POWER,8),2);l.getBlockState(p).tick(l,p,l.getRandom());check(l.getBlockState(p).getValue(RelayBlock.ACTIVE)&&l.getSignal(p,Direction.NORTH)==9&&l.getSignal(p,Direction.SOUTH)==0,"threshold or directional output");l.setBlockAndUpdate(q,Blocks.REDSTONE_BLOCK.defaultBlockState());for(int i=0;i<15;i++)be.adjust(true);check(be.input()==8,"relay wrap 1..15");Thaumcraft.LOGGER.info("AUXILIARY_RELAY_OK: native weak dust strengths 7/8, input threshold, configured output9, direction and independent wraparound");}
 static void recipes(ServerLevel l){int n=0;for(var h:l.recipeAccess().getRecipes())if(h.value() instanceof thaumcraft.crafting.ArcaneRecipe r&&java.util.Set.of("PAVINGSTONES","REDSTONERELAY","ARCANEEAR").contains(r.research())){check(r.vis()==(r.research().equals("PAVINGSTONES")?50:r.research().equals("ARCANEEAR")?15:10),"auxiliary recipe vis");n++;}check(n==4,"auxiliary recipes missing");var table=new thaumcraft.crafting.ArcaneWorkbenchEntity(P,thaumcraft.crafting.ArcaneContent.WORKBENCH.get().defaultBlockState());table.setLevel(l);for(int slot:new int[]{0,1,3,4})table.inventory.setItem(slot,new net.minecraft.world.item.ItemStack(thaumcraft.content.SimpleContent.BLOCKS.get("stone_arcane_brick").get()));table.inventory.setItem(9,thaumcraft.crystals.CrystalContent.essence("aer",1));table.inventory.setItem(12,thaumcraft.crystals.CrystalContent.essence("terra",1));check(table.match()!=null&&table.match().result().is(AuxiliaryContent.TRAVEL.get().asItem())&&table.match().result().getCount()==4,"travel recipe not selectable by crystals");for(int i=9;i<15;i++)table.inventory.setItem(i,net.minecraft.world.item.ItemStack.EMPTY);table.inventory.setItem(10,thaumcraft.crystals.CrystalContent.essence("ignis",1));table.inventory.setItem(13,thaumcraft.crystals.CrystalContent.essence("ordo",1));check(table.match()!=null&&table.match().result().is(AuxiliaryContent.BARRIER.get().asItem())&&table.match().result().getCount()==4,"barrier recipe not selectable by crystals");var input=net.minecraft.world.item.crafting.CraftingInput.of(2,1,java.util.List.of(new net.minecraft.world.item.ItemStack(AuxiliaryContent.EAR.get()),new net.minecraft.world.item.ItemStack(Blocks.LEVER)));var toggle=l.recipeAccess().getRecipeFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING,input,l).orElseThrow();check(toggle.value().assemble(input).is(AuxiliaryContent.TOGGLE.get().asItem()),"native toggle conversion");Thaumcraft.LOGGER.info("AUXILIARY_RECIPES_OK: four original arcane recipes/costs, both stone variants selectable by crystals and native toggle conversion");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode().startsWith("auxiliary-"))return;var l=e.server().overworld();if(++ticks<80)return;if(stage==99){if(mode().equals("auxiliary-client")&&ready&&!framed&&l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE)){actor.teleportTo(l,P.getX()+.5,P.getY()+2,P.getZ()+10.5,java.util.Set.of(),180,26,true);framed=true;Thaumcraft.LOGGER.info("AUXILIARY_REAL_NOTE_OK: real native block interaction latched ear; camera framed for circuit screenshot");}return;}if(stage==0){for(int x=218;x<=222;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);due=l.getGameTime()+80;stage=1;return;}if(l.getGameTime()<due)return;
 if(stage==1){if(mode().equals("auxiliary-read")){var be=(RelayEntity)l.getBlockEntity(P.south(4));check(be.input()==8&&be.output()==9&&l.getSignal(P.south(4),Direction.NORTH)==9,"relay restart settings/output");check(((ArcaneEarEntity)l.getBlockEntity(P)).note()==0&&l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE),"ear restart note/toggle state");Thaumcraft.LOGGER.info("AUXILIARY_RESTART_OK: native relay threshold/output and latched ear survived second JVM");stage=99;e.server().halt(false);return;}
 if(mode().equals("auxiliary-client")&&e.server().getPlayerList().getPlayers().isEmpty())return;
 for(var q:BlockPos.betweenClosed(P.offset(-10,-2,-8),P.offset(10,6,10)))l.setBlockAndUpdate(q,q.getY()==P.getY()-2?Blocks.GLOWSTONE.defaultBlockState():Blocks.AIR.defaultBlockState());recipes(l);ear(l,P,false);ear(l,P.east(2),true);place(l,P.west(6),AuxiliaryContent.BARRIER.get());place(l,P.west(3),AuxiliaryContent.TRAVEL.get());net.minecraftforge.event.level.NoteBlockEvent.Play.BUS.addListener(event->cancel);
 if(mode().equals("auxiliary-client")){actor=e.server().getPlayerList().getPlayers().getFirst();var mount=(LivingEntity)net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getValue(net.minecraft.resources.Identifier.withDefaultNamespace("pig")).create(l,EntitySpawnReason.COMMAND);mount.setPos(Vec3.atBottomCenterOf(P.west(6).above()));l.addFreshEntity(mount);check(actor.startRiding(mount,true,true),"native client mount setup");var field=P.west(6).above();l.setBlockAndUpdate(field,AuxiliaryContent.FIELD.get().defaultBlockState());check(l.getBlockState(field).getCollisionShape(l,field,CollisionContext.of(mount)).isEmpty(),"barrier blocked real player mount");actor.stopRiding();mount.discard();Thaumcraft.LOGGER.info("AUXILIARY_MOUNT_OK: real connected player mount bypasses native barrier collision");actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.getInventory().clearContent();actor.teleportTo(l,P.getX()+3.5,P.getY()+2,P.getZ()+10.5,java.util.Set.of(),180,41.2F,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();((ArcaneEarEntity)l.getBlockEntity(P)).tune();((ArcaneEarEntity)l.getBlockEntity(P.east(2))).tune();relay(l);l.setBlockAndUpdate(P.south(5),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(P.south(6),Blocks.REDSTONE_LAMP.defaultBlockState());l.updateNeighborsAt(P.south(5),Blocks.STONE);place(l,P.east(3).south(7),Blocks.NOTE_BLOCK);ready=true;stage=99;Thaumcraft.LOGGER.info("AUXILIARY_CLIENT_READY: ears, note block, travel/barrier stones and output9 relay in native world; trigger note block with real input");return;}
 due=l.getGameTime()+10;stage=2;return;}
 if(stage==2){paving(l);relay(l);note(l,1);check(!l.getBlockState(P).getValue(ArcaneEarBlock.ACTIVE),"mismatched pitch activated ear");note(l,0);check(l.getBlockState(P).getValue(ArcaneEarBlock.ACTIVE)&&l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE),"native note did not activate both ears");note(l,0);check(l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE),"duplicate same-tick note toggled twice");due=l.getGameTime()+12;stage=3;return;}
 if(stage==3){check(!l.getBlockState(P).getValue(ArcaneEarBlock.ACTIVE)&&l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE),"pulse expiry/toggle latch");cancel=true;note(l,0);check(!l.getBlockState(P).getValue(ArcaneEarBlock.ACTIVE)&&l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE),"cancelled note activated ear");cancel=false;note(l,0);check(!l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE),"toggle second note failed");due=l.getGameTime()+2;stage=4;return;}
 if(stage==4){var support=P.east(2).below();l.setBlockAndUpdate(support,Blocks.STONE.defaultBlockState());note(l,0);check(!l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE),"wrong instrument activated ear");due=l.getGameTime()+2;stage=5;return;}
 if(stage==5){l.setBlockAndUpdate(P.east(2).below(),Blocks.DIRT.defaultBlockState());note(l,0);check(l.getBlockState(P.east(2)).getValue(ArcaneEarBlock.ACTIVE),"support instrument not updated");var remote=ear(l,P.north(65),false);note(l,0);check(!remote.getBlockState().getValue(ArcaneEarBlock.ACTIVE),"ear heard beyond64");remote.tune();check(remote.note()==1,"ear tuning");l.removeBlock(remote.getBlockPos().below(),false);check(l.isEmptyBlock(remote.getBlockPos()),"unsupported ear survived");Thaumcraft.LOGGER.info("AUXILIARY_EARS_OK: real note playback, pitch/instrument/radius filters,10tick pulse, persistent toggle, Forge cancellation, tuning and support drops");var pulsePos=P.south(8);place(l,pulsePos,AuxiliaryContent.RELAY.get());l.setBlockAndUpdate(pulsePos.north(),Blocks.REDSTONE_BLOCK.defaultBlockState());l.removeBlock(pulsePos.north(),false);due=l.getGameTime()+2;stage=6;return;}
 if(stage==6){check(l.getBlockState(P.south(8)).getValue(RelayBlock.ACTIVE),"native diode lost short input pulse");due=l.getGameTime()+3;stage=7;return;}
 if(stage==7){check(!l.getBlockState(P.south(8)).getValue(RelayBlock.ACTIVE),"native diode pulse did not expire");Thaumcraft.LOGGER.info("AUXILIARY_PULSE_OK: real neighbor notifications preserve sub-two-tick input pulse and delayed shutoff");stage=99;e.server().halt(false);}}
}
